INSERT INTO `tenant_agreement_acceptances` VALUES (1,1,2,'f0445812ffee630b8298f8bee00576080270bcbd3836bf84f7bb792358d8cf94','I Mohammed Aminu Shehe totally agree to stay in this PG for 0 Months. I won’t go out unless I have informed the management and followed the terms of my agreement. I agree to contact the Super Admin if I need an extension.','2026-10-10 02:37:01','10.27.160.133','Dart/3.10 (dart:io)'),(2,1,2,'d2dbf2cc8aec325f5db791e03dd91ae3e607165c746b3fd21355f6c2ee15ea8c','I, Mohammed Aminu Shehe, hereby agree to stay in Happy Living PG, Room 402, for the agreed period of 0 Months.\r\n    I will pay a monthly rent of 10000.00 Rs along with a security fee of 10500.00 Rs, payable on 14.\r\n\r\n    I will not vacate the room until the agreed period ends.\r\n    I agree to take care of all equipment and devices in the room and ensure no damage is caused during my stay.\r\n\r\n    I acknowledge my arrival date as 2026-06-14, my residency status as international, and my nationality as Tanzanian.\r\n    For any extension of stay, I agree to contact the Super Admin and follow the terms of this agreement.','2026-10-10 02:51:55','10.27.160.133','Dart/3.10 (dart:io)'),(3,1,2,'3dbeeb1df0b3e9fbad0af34c3922ebe1435a5258c5da0394eb96e5c485f64b36','I, Mohammed Aminu Shehe, hereby agree to stay in Happy Living PG, Room 402, for the agreed period of 6 Months.\r\n    I will pay a monthly rent of 10000.00 Rs along with a security fee of 10500.00 Rs, payable on 14.\r\n\r\n    I will not vacate the room until the agreed period ends.\r\n    I agree to take care of all equipment and devices in the room and ensure no damage is caused during my stay.\r\n\r\n    I acknowledge my arrival date as 2026-06-14, my residency status as international, and my nationality as Tanzanian.\r\n    For any extension of stay, I agree to contact the Super Admin and follow the terms of this agreement.','2026-10-10 03:00:13','10.31.210.5','Dart/3.10 (dart:io)'),(5,18,2,'9113af0519524361252f742b6e25dd020d10822e80de4a4e7e1e677432903b92','I, Sri Ram, hereby agree to stay in Happy Living PG, Room 201, for the agreed period of 0 Months.\r\n    I will pay a monthly rent of 11000.00 Rs along with a security fee of 8000.00 Rs, payable on 1.\r\n\r\n    I will not vacate the room until the agreed period ends.\r\n    I agree to take care of all equipment and devices in the room and ensure no damage is caused during my stay.\r\n\r\n    I acknowledge my arrival date as 2026-08-01, my residency status as national, and my nationality as Indian.\r\n    For any extension of stay, I agree to contact the Super Admin and follow the terms of this agreement.','2026-10-15 14:23:59','10.25.208.9','Dart/3.10 (dart:io)'),(6,1,2,'d2df80e068db672dde707e7e5cd4bd9b83fd8ae8aa0f8c670c1fa3d6767a62d5','LIVINKEY AGREEMENT\r\n\r\nAPARTMENT NAME: Happy Living PG                         ROOM NO.: 402\r\nTIME PERIOD: 6 Months\r\n\r\nTENANT INFORMATION\r\nNAME: Mohammed Aminu Shehe                               MOBILE NO.: +91 7681969865\r\nPARENTS NO.: +255 777730606                         AADHAR/PASSPORT/VISA NO.: null\r\nNATIONALITY: Tanzanian                        GENDER: male\r\n\r\nRENT INFORMATION\r\nDATE OF JOINING: 2026-06-14\r\nMONTHLY RENT AMOUNT RS: 10000.00                    SECURITY DEPOSIT RS: 10500.00\r\n\r\nTERMS & CONDITIONS\r\n1. Tenant shall occupy premises for residential purpose only and not for any other purpose without prior written permission/consent of the owner.\r\n2. Tenant shall return the room in the same condition as it was given at the time of rent agreement. Fixed Rs. 500/- checkout fee is compulsory.\r\n3. Tenant shall not make any addition/alteration in the rented premises without prior consent/permission of the owner and shall not do work which will cause damage.\r\n4. Tenant shall pay rent monthly in the first week of every month on or before the 7th day. Late payment fine: Rs. 100/- per day until payment is received.\r\n5. Tenant cannot vacate before completion of the agreed 10/12-month lock-in and shall give one month\'s prior notice before vacating.\r\n6. Tenant shall provide two identity proofs along with a passport-size photograph.\r\n7. In case of any dispute, the matter shall be referred to Phagwara Court only.\r\n8. Tenant is responsible for any illegal work done in PG premises/room (drugs, fighting or any other illegal work).\r\n9. If tenant is found violating the rules, owner has the right to terminate the agreement and require the tenant to vacate the same day.\r\n10. Electricity bill shall be paid on or before the 5th of every month.\r\n11. Tenant must not misbehave with any staff members of LIVINKEY.\r\n12. Fixed maintenance charges of Rs. 300/- will be taken every month.\r\n13. Security deposit will be refunded upon receipt of written notice to vacate at least one month prior to the end of the lock-in period.\r\n14. Wi-Fi is not an inclusive service provided by LIVINKEY; it is an additional service and LIVINKEY does not guarantee it.\r\n15. No loud music, parties or disturbances are allowed inside the PG premises.\r\n16. LIVINKEY is not responsible for anything stolen inside/outside the room from common areas.\r\n17. Outsiders are not allowed to stay overnight. Only parents are allowed with prior permission.\r\n18. If anything in the room is broken, damaged or stolen, the tenant is responsible and double the amount will be charged.\r\n19. If the tenant loses the door keys, the tenant must pay Rs. 2,000/-.\r\n20. The source agreement states that the first party/owner will not take responsibility in case of injury, mishap or death.\r\n21. If the sub-meter fails, the average charge will be taken.\r\n22. Police verification is the responsibility of the tenant.\r\n23. For international students, C Form is necessary and must be taken 30 days before visa expiry.\r\n24. If the tenant stays beyond the agreement tenure, even for a single day, Rs. 800/- per day will be charged.\r\n25. If rent remains unpaid and tenant fails to respond to LIVINKEY messages or calls for 15 days, LIVINKEY reserves the right to break the lock and vacate the room.','2026-10-17 09:09:21','10.29.247.100','Dart/3.10 (dart:io)'),(7,18,2,'e7c09d60ae029209eec0db3fcd9bce0a80d55c95c6ca05be07671dafbcea4c37','LIVINKEY AGREEMENT\r\n\r\nAPARTMENT NAME: Happy Living PG                         ROOM NO.: 201\r\nTIME PERIOD: 0 Months\r\n\r\nTENANT INFORMATION\r\nNAME: Sri Ram                               MOBILE NO.: +91 9381124050\r\nPARENTS NO.:                          AADHAR/PASSPORT/VISA NO.: 12346789989\r\nNATIONALITY: Indian                        GENDER: male\r\n\r\nRENT INFORMATION\r\nDATE OF JOINING: 2026-08-01\r\nMONTHLY RENT AMOUNT RS: 11000.00                    SECURITY DEPOSIT RS: 8000.00\r\n\r\nTERMS & CONDITIONS\r\n1. Tenant shall occupy premises for residential purpose only and not for any other purpose without prior written permission/consent of the owner.\r\n2. Tenant shall return the room in the same condition as it was given at the time of rent agreement. Fixed Rs. 500/- checkout fee is compulsory.\r\n3. Tenant shall not make any addition/alteration in the rented premises without prior consent/permission of the owner and shall not do work which will cause damage.\r\n4. Tenant shall pay rent monthly in the first week of every month on or before the 7th day. Late payment fine: Rs. 100/- per day until payment is received.\r\n5. Tenant cannot vacate before completion of the agreed 10/12-month lock-in and shall give one month\'s prior notice before vacating.\r\n6. Tenant shall provide two identity proofs along with a passport-size photograph.\r\n7. In case of any dispute, the matter shall be referred to Phagwara Court only.\r\n8. Tenant is responsible for any illegal work done in PG premises/room (drugs, fighting or any other illegal work).\r\n9. If tenant is found violating the rules, owner has the right to terminate the agreement and require the tenant to vacate the same day.\r\n10. Electricity bill shall 